                        </Tooltip>
                      ) : null}
                    </TableCell>
                  </>
              </TableRow>
            )
            return (
              localSupplyMissing ? (
                <Tooltip key={order.id} title={EXTERNAL_WB_SUPPLY_HINT} placement="top" arrow>
                  {row}
                </Tooltip>
              ) : row
            )
          })}
          {!busy && orders.length === 0 ? (
            <TableRow>
              <TableCell colSpan={6}>
                <Box sx={{ py: 8, textAlign: 'center' }}>
                  <Inventory2OutlinedIcon sx={{ fontSize: 42, color: 'text.disabled' }} />
